document.addEventListener('pointerlockchange',()=>{
  dragging=false;clearKeys();
  if(ready)status.textContent=document.pointerLockElement===canvas?'WASD o flechas para caminar · Ratón para mirar · Escape para liberar.':'Clic en el espacio para controlar la mirada. También puedes arrastrar el ratón.';
});
document.addEventListener('pointerlockerror',()=>{
  if(ready)status.textContent='El navegador no capturó el ratón. Puedes arrastrar para mirar y usar WASD/flechas.';
});
const movementCodes=new Set(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight']);
window.addEventListener('keydown',event=>{
  if(event.code==='Escape') {releaseLook();return;}
  if(ready && event.code==='KeyE' && !event.repeat && !event.target.closest('select,input')) {
    event.preventDefault();togglePosture();return;
  }
  if(!ready || event.target.closest('a,button,select,input'))return;
  if(movementCodes.has(event.code) && (document.activeElement===canvas || document.pointerLockElement===canvas)) {
    if(posture) {event.preventDefault();status.textContent='Estás sentado. Pulsa E o «Levantarse» antes de caminar.';return;}
    keyboardKeys.add(event.code);keys.add(event.code);event.preventDefault();
  }
});
window.addEventListener('keyup',event=>{keyboardKeys.delete(event.code);if(![...heldMoves.values()].includes(event.code))keys.delete(event.code);});
window.addEventListener('blur',releaseLook);
window.addEventListener('coral-interfacechange',releaseLook);
window.addEventListener('resize',clearKeys);
document.addEventListener('visibilitychange',()=>{if(document.hidden)releaseLook();});
canvas.addEventListener('webglcontextlost',event=>{event.preventDefault();showFallback('Se perdió el contexto WebGL. Puedes consultar la panorámica.');});
canvas.addEventListener('webglcontextrestored',()=>{
  if(modelLoaded) {
    ready=true;loading.hidden=true;fallback.hidden=true;
    document.querySelectorAll('#empezar,#volver,#ubicacion,#postura,#estatura,[data-move]').forEach(element=>{element.disabled=false;});
    reset();
  }
});
selector.addEventListener('change',()=>{if(ready)reset();});
document.querySelector('#empezar').onclick=requestLook;
document.querySelector('#volver').onclick=()=>{if(ready)reset();};
postureButton.onclick=togglePosture;
statureControl.addEventListener('input',()=>{
  stature=WalkCore.statureMeters(statureControl.value);
  camera.position.y=cameraHeight();updatePerson();
});
updatePerson();
document.querySelector('#ayuda').onclick=event=>{
  const help=document.querySelector('#instrucciones');help.hidden=!help.hidden;
  event.currentTarget.setAttribute('aria-expanded',String(!help.hidden));
};
document.querySelector('#pantalla').onclick=async()=>{
  try {
    if(document.fullscreenElement)await document.exitFullscreen();
    else await document.documentElement.requestFullscreen();
  } catch(error) {status.textContent='Este navegador no permite pantalla completa.';}
};
for(const button of document.querySelectorAll('[data-move]')) {
  button.addEventListener('pointerdown',event=>{
    if(!ready)return;event.preventDefault();canvas.focus();
    if(posture) {status.textContent='Estás sentado. Pulsa «Levantarse» antes de caminar.';return;}
    button.setPointerCapture(event.pointerId);heldMoves.set(event.pointerId,button.dataset.move);keys.add(button.dataset.move);button.setAttribute('aria-pressed','true');
  });
  for(const name of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(name,event=>{
    heldMoves.delete(event.pointerId);
    const held=[...heldMoves.values()].includes(button.dataset.move);
    if(!held&&!keyboardKeys.has(button.dataset.move))keys.delete(button.dataset.move);
    button.setAttribute('aria-pressed',String(held));
  });
  button.addEventListener('keydown',event=>{
    if(['Space','Enter'].includes(event.code)&&ready&&!posture){event.preventDefault();keys.add(button.dataset.move);button.setAttribute('aria-pressed','true');}
  });
  button.addEventListener('keyup',event=>{
    if(['Space','Enter'].includes(event.code)){keys.delete(button.dataset.move);button.setAttribute('aria-pressed','false');}
  });
  button.addEventListener('blur',()=>{if(![...heldMoves.values()].includes(button.dataset.move)){keys.delete(button.dataset.move);button.setAttribute('aria-pressed','false');}});
}
window.addEventListener('resize',resize);resize();
async function loadModel() {
  try {
    if(typeof DecompressionStream!=='function')throw new Error('Native gzip decompression unavailable');
    await CORAL_R1.afterPaint();
    const bytes=(await CORAL_R1.unpack(MODEL_GZIP)).buffer;
    const nativeDetail=NAV.surface_detail?JSON.parse(new TextDecoder().decode(await CORAL_R1.unpack("walk:detail"))):[];
    const gltf=await new Promise((resolve,reject)=>new THREE.GLTFLoader().parse(bytes,'',resolve,reject));
    const maps=NAV.surface_detail?WalkSurfaces.createTextures(THREE,nativeDetail):null;
    if(maps)WalkSurfaces.createReflections(THREE,scene,NAV);
    gltf.scene.traverse(object=>{
      if(object.isMesh) {
        if(NAV.baked_lighting) {
          if(maps)WalkSurfaces.prepareMaterial(THREE,object,maps);
          else object.material=new THREE.MeshBasicMaterial({color:0xffffff,vertexColors:true,
            side:Array.isArray(object.material)?object.material[0].side:object.material.side,toneMapped:false});
          object.castShadow=false;object.receiveShadow=false;
          if(object.userData.web_plain_curtain)curtain=WalkSurfaces.curtainState(object);
        } else {object.castShadow=true;object.receiveShadow=true;WalkLighting.prepareMaterials(object);}
      }
    });
    scene.add(gltf.scene);modelLoaded=true;ready=true;CORAL_R1.ready();CORAL_R1.release(MODEL_GZIP);
    document.querySelectorAll('#empezar,#volver,#ubicacion,#postura,#estatura,[data-move]').forEach(element=>{element.disabled=false;});
    loading.hidden=true;fallback.hidden=true;reset('entrada');
  } catch(error) {showFallback('No fue posible abrir el modelo en este navegador. Puedes consultar la panorámica.');}
}
function frame(time) {
  const dt=lastTime?Math.min((time-lastTime)/1000,.05):0;lastTime=time;
  if(ready && !document.hidden) {
    const step=WalkCore.smoothMovement(velocity,keys,yaw,NAV.camera?.walk_speed_m_s||1.45,dt,NAV.camera?.velocity_response_s||.14);
    velocity=posture?{x:0,z:0}:step.velocity;
    if(!posture)position=WalkCore.move(position,step.delta.x,step.delta.z,NAV,NAV.radius);
    camera.position.set(position.x,cameraHeight(),position.z);
    camera.rotation.set(pitch,yaw,0,'YXZ');
    WalkSurfaces.updateCurtain(curtain,position,dt);
  }
  if(renderer)renderer.render(scene,camera);
  requestAnimationFrame(frame);
}
if(renderer) {loadModel();requestAnimationFrame(frame);}
